26	    public override async Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
27	    {
28	        StampAuditFields();
29	        return await base.SaveChangesAsync(cancellationToken);
30	    }
31	
32	    private void StampAuditFields()
33	    {
34	        var now = _time.GetUtcNow().DateTime;
35	
36	        foreach (var entry in ChangeTracker.Entries<CmEntity>())
37	        {
38	            if (entry.State == EntityState.Added)
39	                entry.Entity.CreatedDate = now;
40	
41	            if (entry.State is EntityState.Added or EntityState.Modified)
42	                entry.Entity.LastUpdatedDate = now;
43	        }
44	    }
45	
46	    private static void ApplyUtcDateTimeConverters(ModelBuilder modelBuilder)
47	    {
48	        var utcConverter = new ValueConverter<DateTime, DateTime>(
49	            v => EnforceUtc(v),
50	            v => DateTime.SpecifyKind(v, DateTimeKind.Utc)
51	        );
52	
53	        var utcNullableConverter = new ValueConverter<DateTime?, DateTime?>(
54	            v => EnforceUtcNullable(v),
55	            v => v == null ? null : DateTime.SpecifyKind(v.Value, DateTimeKind.Utc)
56	        );
57	
58	        foreach (var entityType in modelBuilder.Model.GetEntityTypes())
59	        foreach (var property in entityType.GetProperties())
60	        {
61	            if (property.ClrType == typeof(DateTime))
62	                property.SetValueConverter(utcConverter);
63	            else if (property.ClrType == typeof(DateTime?))
64	                property.SetValueConverter(utcNullableConverter);
65	        }
66	    }
67	
68	    private static DateTime EnforceUtc(DateTime v) =>
69	        v.Kind == DateTimeKind.Utc
70	            ? v
71	            : throw new InvalidOperationException($"Non-UTC DateTime written to database: {v}");
72	
73	    private static DateTime? EnforceUtcNullable(DateTime? v) =>
74	        v is null || v.Value.Kind == DateTimeKind.Utc
75	            ? v
76	            : throw new InvalidOperationException($"Non-UTC DateTime written to database: {v}");
