5	namespace CabinetMaker.BRL.Services;
6	
7	public class DbSeeder
8	{
9	    private readonly UserManager<User> _userManager;
10	    private readonly RoleManager<IdentityRole<int>> _roleManager;
11	    private readonly BrlServiceConfiguration _config;
12	
13	    public DbSeeder(UserManager<User> userManager, RoleManager<IdentityRole<int>> roleManager, BrlServiceConfiguration config)
14	    {
15	        _userManager = userManager;
16	        _roleManager = roleManager;
17	        _config = config;
18	    }
19	
20	    public async Task SeedAsync()
21	    {
22	        await SeedRolesAsync();
23	        await SeedAdminAsync();
24	    }
25	
26	    private async Task SeedRolesAsync()
27	    {
28	        string[] roles = ["Admin", "TenantAdmin", "User"];
29	        foreach (var role in roles)
30	        {
31	            if (!await _roleManager.RoleExistsAsync(role))
32	                await _roleManager.CreateAsync(new IdentityRole<int>(role));
33	        }
34	    }
35	
36	    private async Task SeedAdminAsync()
37	    {
38	        if (string.IsNullOrEmpty(_config.AdminEmail)) return;
39	        if (await _userManager.FindByEmailAsync(_config.AdminEmail) is not null) return;
40	
41	        var admin = new User
42	        {
43	            UserGuid = Guid.NewGuid(),
44	            UserName = _config.AdminEmail,
45	            Email = _config.AdminEmail,
46	            DisplayName = _config.AdminDisplayName,
47	            EmailConfirmed = true
48	        };
49	
50	        var result = await _userManager.CreateAsync(admin, _config.AdminPassword);
51	        if (result.Succeeded)
52	            await _userManager.AddToRoleAsync(admin, "Admin");
53	    }
54	}
